package dev.codex.phonespeed;
import android.app.Instrumentation;
import android.app.UiAutomation;
import android.os.Bundle;
import android.os.SystemClock;
import android.util.Base64;
import android.graphics.Rect;
import android.view.MotionEvent;
import android.view.InputDevice;
import android.view.accessibility.AccessibilityNodeInfo;
import org.json.JSONObject;
public class Bench extends Instrumentation {
 Bundle args; UiAutomation ui;
 public void onCreate(Bundle a){args=a;start();}
 static AccessibilityNodeInfo find(AccessibilityNodeInfo n,String kind){if(n==null)return null;String d=String.valueOf(n.getContentDescription()),t=String.valueOf(n.getText());if(n.isVisibleToUser()&&((kind.equals("edit")&&n.isEditable())||(kind.equals("send")&&d.equals("发送"))||(kind.equals("new")&&d.equals("开启新对话"))||(kind.equals("answer")&&!n.isEditable()&&(t.startsWith("完整 Markdown 功能演示")||t.startsWith("# 完整 Markdown 功能演示")))))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo f=find(n.getChild(i),kind);if(f!=null)return f;}return null;}
 static void tree(AccessibilityNodeInfo n,StringBuilder b,int depth){if(n==null||depth>30)return;String t=""+n.getText(),d=""+n.getContentDescription();if(!t.equals("null")||!d.equals("null")||n.isEditable())b.append(n.getClassName()).append(" text=").append(t).append(" desc=").append(d).append(" editable=").append(n.isEditable()).append("\n");for(int i=0;i<n.getChildCount();i++)tree(n.getChild(i),b,depth+1);}
 static void controls(AccessibilityNodeInfo n,StringBuilder b){if(n==null)return;CharSequence d=n.getContentDescription();if(d!=null)b.append(d).append("|");for(int i=0;i<n.getChildCount();i++)controls(n.getChild(i),b);}
 AccessibilityNodeInfo root() {ui.clearCache();return ui.getRootInActiveWindow();}
 void click(AccessibilityNodeInfo n)throws Exception{if(n==null)throw new Exception("No target");Rect r=new Rect();n.getBoundsInScreen(r);long t=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,r.centerX(),r.centerY(),0);down.setSource(InputDevice.SOURCE_TOUCHSCREEN);ui.injectInputEvent(down,true);MotionEvent up=MotionEvent.obtain(t,t+10,MotionEvent.ACTION_UP,r.centerX(),r.centerY(),0);up.setSource(InputDevice.SOURCE_TOUCHSCREEN);ui.injectInputEvent(up,true);down.recycle();up.recycle();}
 public void onStart(){Bundle result=new Bundle();try{ui=getUiAutomation();android.accessibilityservice.AccessibilityServiceInfo info=ui.getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS|android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;ui.setServiceInfo(info);AccessibilityNodeInfo root=null;for(int i=0;i<20&&root==null;i++){SystemClock.sleep(100);root=root();}if(root==null)throw new Exception("No accessibility root");String mode=args.getString("mode", "dump");if(mode.equals("fill")){AccessibilityNodeInfo e=find(root,"edit");if(e==null)throw new Exception("No editable field");String text=new String(Base64.decode(args.getString("text"),Base64.DEFAULT),"UTF-8");Bundle x=new Bundle();x.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,text);result.putBoolean("success",e.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,x));result.putInt("chars",text.length());}else if(mode.equals("new")){click(find(root,"new"));result.putBoolean("success",true);}else if(mode.equals("measure")){AccessibilityNodeInfo send=find(root,"send");if(send==null)throw new Exception("No send button");long start=SystemClock.elapsedRealtime();click(send);long first=-1;boolean sawStop=false;String previous="";for(int i=0;i<1800;i++){root=root();long elapsed=SystemClock.elapsedRealtime()-start;StringBuilder c=new StringBuilder();controls(root,c);String cs=c.toString();if(!cs.equals(previous)){Bundle update=new Bundle();update.putString("controls",elapsed+"ms "+cs);sendStatus(0,update);previous=cs;}if(cs.contains("停止"))sawStop=true;if(first<0&&find(root,"answer")!=null){first=elapsed;Bundle update=new Bundle();update.putLong("firstBodyMs",first);sendStatus(0,update);}if(first>=0&&sawStop&&!cs.contains("停止")){JSONObject row=new JSONObject();row.put("firstBodyMs",first);row.put("totalMs",elapsed);row.put("stopSeen",sawStop);row.put("finalControls",cs);result.putString("measurement",row.toString());StringBuilder b=new StringBuilder();tree(root,b,0);result.putString("finalTree",b.toString());finish(0,result);return;}SystemClock.sleep(50);}throw new Exception("Completion not detected; first="+first+" stopSeen="+sawStop);}else{StringBuilder b=new StringBuilder();tree(root,b,0);result.putString("tree",b.toString());}finish(0,result);}catch(Throwable e){result.putString("error",e.toString());finish(1,result);}}
}
